select jsonb_build_object('observed_at',current_timestamp,'api_schema_setting',current_setting('pgrst.db_schemas',true),'core_users_column_privileges',(select jsonb_agg(jsonb_build_object('column',a.attname,'auth_update',has_column_privilege('authenticated',c.oid,a.attnum,'UPDATE'),'anon_update',has_column_privilege('anon',c.oid,a.attnum,'UPDATE'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid where n.nspname='core' and c.relname='users' and a.attname in ('id','role','is_active')),'core_users_triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'function',p.proname)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid where n.nspname='core' and c.relname='users' and not t.tgisinternal)) as inspection;
